// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { computeSquareLayout } from "../../../main/frontend/graph-explorer/graph-layout-square.ts";
import { graphNodeSize } from "../../../main/frontend/graph-explorer/graph-geometry.ts";

const node = (id, x, y, label = "Readable node") => ({ id, kind: "iri", label, x, y });

test("nine nodes fill a 3×3 grid in the order a person reads them on the canvas", () => {
  // Three loose rows, listed out of order: the grid follows where the nodes stand, not the list.
  const nodes = [
    node("i", 620, 405), node("e", 320, 190), node("a", 10, 0),
    node("g", 5, 400), node("c", 600, -5), node("h", 290, 395),
    node("b", 300, 5), node("f", 610, 210), node("d", 0, 200),
  ];
  const positions = computeSquareLayout({ nodes, edges: [], revision: 1 });
  const at = (id) => positions.get(id);
  for (const row of [["a", "b", "c"], ["d", "e", "f"], ["g", "h", "i"]]) {
    assert.equal(new Set(row.map((id) => at(id).y)).size, 1, `${row} share a row`);
    assert.ok(at(row[0]).x < at(row[1]).x && at(row[1]).x < at(row[2]).x, `${row} read left to right`);
  }
  for (const column of [["a", "d", "g"], ["b", "e", "h"], ["c", "f", "i"]]) {
    assert.equal(new Set(column.map((id) => at(id).x)).size, 1, `${column} share a column`);
    assert.ok(at(column[0]).y < at(column[1]).y && at(column[1]).y < at(column[2]).y);
  }
  const size = graphNodeSize(nodes[0]);
  assert.ok(at("b").x - at("a").x >= size.width + 48, "48px between columns");
  assert.ok(at("d").y - at("a").y >= size.height + 36, "36px between rows");
  const xs = [...positions.values()].map((p) => p.x), ys = [...positions.values()].map((p) => p.y);
  assert.ok(Math.abs(Math.min(...xs) + Math.max(...xs)) < 1e-9, "centred horizontally on the origin");
  assert.ok(Math.abs(Math.min(...ys) + Math.max(...ys)) < 1e-9, "centred vertically on the origin");
});

test("five nodes make three columns and two rows; a wide label widens only its own column", () => {
  const nodes = [
    node("a", 0, 0), node("b", 100, 0, "A much longer label that needs a wider card"), node("c", 200, 0),
    node("d", 0, 100), node("e", 100, 100),
  ];
  const positions = computeSquareLayout({ nodes, edges: [], revision: 1 });
  assert.equal(new Set([...positions.values()].map((p) => p.y)).size, 2);
  assert.equal(new Set([...positions.values()].map((p) => p.x)).size, 3);
  const narrow = graphNodeSize(nodes[0]).width, wide = graphNodeSize(nodes[1]).width;
  assert.ok(wide > narrow);
  // Neighbouring columns are as far apart as half of each column's width plus the gap.
  assert.ok(Math.abs(positions.get("b").x - positions.get("a").x - (narrow / 2 + 48 + wide / 2)) < 1e-9);
  assert.ok(Math.abs(positions.get("c").x - positions.get("b").x - (wide / 2 + 48 + narrow / 2)) < 1e-9);
});
